import type { FileManagerMessages } from './messages'
import type { FileManagerColumn, FileManagerColumnKey, FileManagerItem } from './types'
import { formatBytes, formatRelativeTime, getFileExtension, getFileKind, isFolder, toDate } from './utils'

/** A details column with everything needed to render it. */
export interface ResolvedColumn<TData> {
  key: string
  label: string
  /** CSS grid track. */
  width: string
  align: 'start' | 'end'
  sortable: boolean
  /** Stays visible on narrow file managers. */
  pinned: boolean
  format: (item: FileManagerItem<TData>) => string
  title?: (item: FileManagerItem<TData>) => string | undefined
  /** The consumer's definition, for the `cell` slot. */
  source: FileManagerColumn<TData>
}

export const DEFAULT_COLUMNS: FileManagerColumnKey[] = ['name', 'modified', 'type', 'size']

type BuiltIn<TData> = Pick<ResolvedColumn<TData>, 'width' | 'format'> & Partial<Pick<ResolvedColumn<TData>, 'align' | 'title'>>

/** The kind of item ("TypeScript", "Image", "Folder"), translated. `description` is free text and is not used. */
export function describeKind<TData>(item: FileManagerItem<TData>, messages: FileManagerMessages): string {
  const kind = getFileKind(item)
  return messages.fileKind(kind.category, getFileExtension(item), kind.label)
}

function builtIns<TData>(messages: FileManagerMessages, now: () => Date): Partial<Record<string, BuiltIn<TData>>> {
  const date = (pick: (item: FileManagerItem<TData>) => Date | string | undefined): BuiltIn<TData> => ({
    width: '6.5rem',
    format: item => formatRelativeTime(pick(item), now(), messages),
    title: item => toDate(pick(item))?.toLocaleString(),
  })
  return {
    name: { width: 'minmax(0, 1fr)', format: item => item.name },
    modified: date(item => item.modifiedAt),
    created: date(item => item.createdAt),
    accessed: date(item => item.accessedAt),
    type: { width: '9rem', format: item => describeKind(item, messages) },
    size: {
      width: '5.5rem',
      align: 'end',
      format: item => (isFolder(item) ? (item.children ? messages.items(item.children.length) : '') : formatBytes(item.size, messages)),
    },
    owner: { width: '8rem', format: item => item.owner ?? '' },
    permissions: { width: '6rem', format: item => (item.permissions?.write === false ? messages.readOnly : messages.canEdit) },
  }
}

/** Normalizes the `columns` prop: strings become built-in columns, and Name is always there. */
export function columnDefinitions<TData>(columns: (FileManagerColumnKey | FileManagerColumn<TData>)[] | undefined): FileManagerColumn<TData>[] {
  const definitions = (columns ?? DEFAULT_COLUMNS).map(column => (typeof column === 'string' ? { key: column } : column))
  return definitions.some(column => column.key === 'name') ? definitions : [{ key: 'name' }, ...definitions]
}

/** The narrowest the name column may get before other columns make room for it, in rem. */
export const NAME_MIN_WIDTH = 12
/** Gap between details columns (`gap-3`), in rem. */
const COLUMN_GAP = 0.75
/** Width of the selection checkbox track, in rem. */
export const CHECK_WIDTH = '1.25rem'

/** The minimum a track needs, in rem: the first rem or px length in it (`8rem`, `minmax(6rem, 1fr)`), else 0. */
export function trackMinWidth(width: string): number {
  const match = width.match(/(\d*\.?\d+)(rem|px)/)
  if (!match) return 0
  return match[2] === 'px' ? Number(match[1]) / 16 : Number(match[1])
}

/**
 * The columns that fit in `available` rem while the name keeps `NAME_MIN_WIDTH`.
 * Unpinned columns give way from the last one backwards; pinned ones always stay.
 * An unknown width (0, before the first measurement or during SSR) keeps every column.
 */
export function fitColumns<TData>(columns: ResolvedColumn<TData>[], available: number, check: boolean): ResolvedColumn<TData>[] {
  if (available <= 0) return columns
  const needed = (list: ResolvedColumn<TData>[]) => {
    const tracks = list.length + (check ? 1 : 0)
    const widths = list.reduce((sum, column) => sum + (column.key === 'name' ? NAME_MIN_WIDTH : trackMinWidth(column.width)), 0)
    return widths + (check ? trackMinWidth(CHECK_WIDTH) : 0) + COLUMN_GAP * Math.max(0, tracks - 1)
  }
  const fitted = [...columns]
  while (needed(fitted) > available) {
    const index = fitted.findLastIndex(column => !column.pinned)
    if (index < 0) break
    fitted.splice(index, 1)
  }
  return fitted
}

/** Resolves labels, widths, formatting and sortability. `now` is read at render time. */
export function resolveColumns<TData>(
  definitions: FileManagerColumn<TData>[],
  messages: FileManagerMessages,
  now: () => Date,
): ResolvedColumn<TData>[] {
  const known = builtIns<TData>(messages, now)
  const labels: Record<string, string> = messages.columns
  return definitions.map((definition) => {
    const base = known[definition.key]
    const value = definition.value
    const fallback = (item: FileManagerItem<TData>) => {
      const raw = value?.(item)
      return raw instanceof Date ? formatRelativeTime(raw, now(), messages) : raw === undefined ? '' : String(raw)
    }
    return {
      key: definition.key,
      label: definition.label ?? labels[definition.key] ?? definition.key,
      width: definition.width ?? base?.width ?? '8rem',
      align: definition.align ?? base?.align ?? 'start',
      sortable: definition.sortable ?? (base !== undefined || value !== undefined),
      pinned: definition.pinned ?? (definition.key === 'name' || definition.key === 'size'),
      format: definition.format ?? base?.format ?? fallback,
      title: base?.title,
      source: definition,
    }
  })
}

import { computed, ref, watch, type Ref } from 'vue'
import { getAncestorIds, type FileManagerIndex } from './utils'

interface UseFileManagerNavigationOptions<TData> {
  /** The open folder, `null` for the root. May point at an id that no longer exists. */
  folder: Ref<string | null>
  index: Readonly<Ref<FileManagerIndex<TData>>>
}

/**
 * Back / Forward / Up over folder ids, like a browser history. Changes made
 * from outside (`v-model:folder`) are recorded too.
 */
export function useFileManagerNavigation<TData>(options: UseFileManagerNavigationOptions<TData>) {
  const { folder, index } = options

  /** The open folder, falling back to the root when it was deleted or never existed. */
  const current = computed(() => {
    const id = folder.value
    return id !== null && index.value.get(id)?.item.type === 'folder' ? id : null
  })

  const history = ref<(string | null)[]>([current.value])
  const position = ref(0)

  watch(current, (id) => {
    if (history.value[position.value] === id) return
    history.value = [...history.value.slice(0, position.value + 1), id]
    position.value = history.value.length - 1
  })

  function go(to: number) {
    position.value = to
    folder.value = history.value[to] ?? null
  }

  const canGoBack = computed(() => position.value > 0)
  const canGoForward = computed(() => position.value < history.value.length - 1)
  const parentId = computed(() => (current.value === null ? null : index.value.get(current.value)?.parentId ?? null))

  return {
    current,
    /** Folder ids from the root down to the open folder. */
    path: computed(() => getAncestorIds(index.value, current.value)),
    canGoBack,
    canGoForward,
    canGoUp: computed(() => current.value !== null),
    navigate(id: string | null) {
      folder.value = id
    },
    back() {
      if (canGoBack.value) go(position.value - 1)
    },
    forward() {
      if (canGoForward.value) go(position.value + 1)
    },
    /** Opens the parent folder and returns the folder that was left, so it can be re-selected. */
    up(): string | null {
      const left = current.value
      if (left === null) return null
      folder.value = parentId.value
      return left
    },
  }
}

import { ref, type Ref } from 'vue'

interface UseFileManagerSelectionOptions {
  selected: Ref<string[]>
  multiple: Readonly<Ref<boolean>>
  /** Items on screen, in order. Ranges are computed over this list. */
  visibleIds: Readonly<Ref<string[]>>
  isSelectable: (id: string) => boolean
}

/**
 * Desktop-style selection over item ids: click replaces, Ctrl/Cmd toggles,
 * Shift extends a range from the last anchor.
 */
export function useFileManagerSelection(options: UseFileManagerSelectionOptions) {
  const { selected, multiple, visibleIds, isSelectable } = options
  const anchor = ref<string | null>(null)

  function replace(id: string) {
    selected.value = [id]
    anchor.value = id
  }

  function toggle(id: string) {
    if (!multiple.value) return replace(id)
    selected.value = selected.value.includes(id)
      ? selected.value.filter(value => value !== id)
      : [...selected.value, id]
    anchor.value = id
  }

  /** Selects everything between the anchor and `id`. The anchor stays put. */
  function extend(id: string) {
    const ids = visibleIds.value
    const from = anchor.value === null ? -1 : ids.indexOf(anchor.value)
    const to = ids.indexOf(id)
    if (!multiple.value || from === -1 || to === -1) return replace(id)

    const [start, end] = from < to ? [from, to] : [to, from]
    selected.value = ids.slice(start, end + 1).filter(isSelectable)
  }

  function selectAll() {
    if (!multiple.value) return
    selected.value = visibleIds.value.filter(isSelectable)
  }

  function clear() {
    selected.value = []
    anchor.value = null
  }

  return { anchor, replace, toggle, extend, selectAll, clear }
}

import type { Ref } from 'vue'
import type { FileManagerView } from './types'

interface UseFileManagerKeyboardOptions {
  /** Items in the open folder, in display order. */
  ids: Readonly<Ref<string[]>>
  focusedId: Ref<string | null>
  view: Readonly<Ref<FileManagerView>>
  multiple: Readonly<Ref<boolean>>
  isSelectable: (id: string) => boolean
  nameOf: (id: string) => string
  /** Number of cards per row in the grid view. */
  columns: () => number
  /** Moves DOM focus to an item. */
  focus: (id: string) => void
  replace: (id: string) => void
  toggle: (id: string) => void
  extend: (id: string) => void
  selectAll: () => void
  clear: () => void
  open: (id: string) => void
  back: () => void
  forward: () => void
  up: () => void
  remove?: () => void
  rename?: () => void
  /** In right-to-left layouts, ArrowLeft moves forward in the grid. */
  dir?: Readonly<Ref<'ltr' | 'rtl'>>
}

const TYPEAHEAD_RESET = 700

/**
 * Desktop file manager keys for the content area. Arrows move in two
 * dimensions in the grid; Shift extends the selection, Ctrl/Cmd moves focus
 * without selecting (Space then toggles), and typing jumps to a name.
 */
export function useFileManagerKeyboard(options: UseFileManagerKeyboardOptions) {
  const rtl = () => options.dir?.value === 'rtl'
  let typeahead = ''
  let typeaheadTimer: ReturnType<typeof setTimeout> | undefined

  function moveTo(id: string, event: KeyboardEvent) {
    options.focusedId.value = id
    options.focus(id)
    if (event.shiftKey && options.multiple.value) options.extend(id)
    else if (!(event.ctrlKey || event.metaKey)) options.replace(id)
  }

  function offset(key: string): number | 'start' | 'end' | undefined {
    const grid = options.view.value === 'grid'
    switch (key) {
      case 'ArrowDown': return grid ? options.columns() : 1
      case 'ArrowUp': return grid ? -options.columns() : -1
      case 'ArrowRight': return grid ? (rtl() ? -1 : 1) : undefined
      case 'ArrowLeft': return grid ? (rtl() ? 1 : -1) : undefined
      case 'Home': return 'start'
      case 'End': return 'end'
    }
    return undefined
  }

  function runTypeahead(key: string): boolean {
    clearTimeout(typeaheadTimer)
    typeahead += key.toLowerCase()
    typeaheadTimer = setTimeout(() => { typeahead = '' }, TYPEAHEAD_RESET)

    const ids = options.ids.value
    const from = options.focusedId.value === null ? 0 : ids.indexOf(options.focusedId.value)
    // A single repeated letter cycles through the matches, as in Explorer and Finder.
    const cycling = typeahead.length > 1 && [...typeahead].every(char => char === typeahead[0])
    const needle = cycling ? typeahead[0] ?? '' : typeahead
    const start = cycling || typeahead.length === 1 ? from + 1 : from
    const ordered = [...ids.slice(start), ...ids.slice(0, start)]
    return ordered.some((id) => {
      if (!options.nameOf(id).toLowerCase().startsWith(needle)) return false
      options.focusedId.value = id
      options.focus(id)
      options.replace(id)
      return true
    })
  }

  function onKeydown(event: KeyboardEvent) {
    const ids = options.ids.value
    const current = options.focusedId.value
    const index = current === null ? -1 : ids.indexOf(current)

    if (event.altKey) {
      if (event.key === 'ArrowLeft') options.back()
      else if (event.key === 'ArrowRight') options.forward()
      else if (event.key === 'ArrowUp') options.up()
      else return
      event.preventDefault()
      return
    }

    const step = offset(event.key)
    if (step !== undefined) {
      if (!ids.length) return
      event.preventDefault()
      let target: number
      if (step === 'start') target = 0
      else if (step === 'end') target = ids.length - 1
      else if (index === -1) target = 0
      else target = Math.min(ids.length - 1, Math.max(0, index + step))
      const id = ids[target]
      if (id !== undefined) moveTo(id, event)
      return
    }

    const mod = event.ctrlKey || event.metaKey
    switch (event.key) {
      case 'Enter':
        if (current !== null) {
          event.preventDefault()
          options.open(current)
        }
        return
      case ' ':
        if (current === null || !options.isSelectable(current)) return
        event.preventDefault()
        if (options.multiple.value) options.toggle(current)
        else options.replace(current)
        return
      case 'Backspace':
        event.preventDefault()
        options.up()
        return
      case 'Escape':
        options.clear()
        return
      case 'Delete':
        if (options.remove) {
          event.preventDefault()
          options.remove()
        }
        return
      case 'F2':
        if (options.rename) {
          event.preventDefault()
          options.rename()
        }
        return
    }

    if (mod && event.key.toLowerCase() === 'a') {
      event.preventDefault()
      options.selectAll()
      return
    }

    if (event.key.length === 1 && !mod && event.key !== ' ') {
      if (runTypeahead(event.key)) event.preventDefault()
    }
  }

  return { onKeydown }
}

import { computed, useId } from 'vue'
import { injectFileManagerContext } from './context'
import type { FileManagerItem } from './types'
import { formatBytes, formatRelativeTime, getFileExtension, getFileKind, isFolder } from './utils'

/**
 * A grid card and a details row are each split in two components, for speed in
 * large folders: a root that owns the option element (selection, focus, drag
 * state) and a body with the content. Focus and selection changes then patch a
 * few attributes on the roots instead of rendering every item again, and the
 * bodies only render when their own item changes.
 *
 * Every piece of state below is its own computed of a primitive: Vue only
 * propagates a computed whose value changed, so moving focus from one item to
 * the next touches those two items, not the whole folder.
 */

/** The option element: `role="option"`, roving tab stop, drag source and (for folders) drop target. */
export function useFileManagerItemRoot<TData>(item: () => FileManagerItem<TData>) {
  const ctx = injectFileManagerContext()

  const id = computed(() => item().id)
  const folder = computed(() => isFolder(item()))
  const disabled = computed(() => Boolean(item().disabled))
  const selected = computed(() => ctx.selected.value.has(id.value))
  const focused = computed(() => ctx.focusedId.value === id.value)
  const cut = computed(() => ctx.cutIds.value.has(id.value))
  const dragging = computed(() => ctx.draggingIds.value.has(id.value))
  const dropTarget = computed(() => ctx.dragDrop.dropTargetId.value === id.value)
  const dropInvalid = computed(() => ctx.dragDrop.invalidTargetId.value === id.value)
  const renaming = computed(() => ctx.renamingId.value === id.value)
  const status = computed(() => ctx.itemOperation(id.value)?.status)
  // Paused while renaming, so selecting text in the input does not start a drag.
  const draggable = computed(() => ctx.draggable.value && !disabled.value && !renaming.value)

  // Options are named by the item's name alone and described by a short summary
  // (see the body), so a screen reader does not read a card's preview as its name.
  const nameId = useId()
  const descriptionId = useId()

  // Created once: listeners that change identity would be re-bound on each patch.
  const listeners = {
    onClick: (event: MouseEvent) => ctx.onItemClick(id.value, event),
    onDblclick: () => ctx.onItemOpen(id.value),
    onContextmenu: () => ctx.onItemContextMenu(id.value),
    onDragstart: (event: DragEvent) => ctx.dragDrop.onDragStart(id.value, event),
    onDragover: (event: DragEvent) => {
      // Files forward drops to their folder, which is the open one: a no-op the
      // drag session refuses. Folders accept the drop themselves.
      if (!folder.value) return
      ctx.dragDrop.onDragOver(id.value, event)
      event.stopPropagation()
    },
    onDrop: (event: DragEvent) => {
      if (!folder.value) return
      event.stopPropagation()
      ctx.dragDrop.onDrop(event)
    },
    onDragend: () => ctx.dragDrop.onDragEnd(),
  }

  const attrs = computed(() => ({
    'role': 'option',
    'aria-selected': selected.value,
    'aria-disabled': disabled.value || undefined,
    'aria-busy': status.value === 'running' || status.value === 'pending' || undefined,
    'aria-labelledby': nameId,
    'aria-describedby': descriptionId,
    'tabindex': focused.value ? 0 : -1,
    'data-item-id': id.value,
    'data-selected': selected.value ? '' : undefined,
    'data-disabled': disabled.value ? '' : undefined,
    'data-cut': cut.value ? '' : undefined,
    'data-dragging': dragging.value ? '' : undefined,
    'data-drop-target': dropTarget.value ? '' : undefined,
    'data-drop-invalid': dropInvalid.value ? '' : undefined,
    'data-operation': status.value,
    'draggable': draggable.value ? true : undefined,
    ...listeners,
  }))

  return { attrs, nameId, descriptionId }
}

/** What a card or row shows. Nothing here depends on selection or focus. */
export function useFileManagerItemContent<TData>(item: () => FileManagerItem<TData>) {
  const ctx = injectFileManagerContext()

  const id = computed(() => item().id)
  const renaming = computed(() => ctx.renamingId.value === id.value)
  const favorite = computed(() => ctx.favorites.value.has(id.value))
  const operation = computed(() => ctx.itemOperation(id.value))
  const busy = computed(() => operation.value?.status === 'running' || operation.value?.status === 'pending')

  // Strings, so the minute clock re-renders an item only when its label changes
  // ("10m ago" → "11m ago"), not every item every minute.
  const modified = computed(() => formatRelativeTime(item().modifiedAt, ctx.now.value, ctx.messages.value))
  const description = computed(() => {
    const current = item()
    const m = ctx.messages.value
    const kind = getFileKind(current)
    const summary = isFolder(current)
      ? [m.folder, current.children ? m.items(current.children.length) : '']
      : [m.fileKind(kind.category, getFileExtension(current), kind.label), formatBytes(current.size, m)]
    return [
      ...summary,
      modified.value,
      favorite.value ? m.starred : '',
      current.permissions?.write === false ? m.readOnly : '',
      operation.value ? [operation.value.label, operation.value.error].filter(Boolean).join(': ') : '',
    ].filter(Boolean).join(m.listSeparator)
  })

  const rename = {
    validate: (name: string) => ctx.validateRename(id.value, name),
    commit: (name: string) => ctx.commitRename(id.value, name),
    cancel: () => ctx.cancelRename(id.value),
  }

  return {
    renaming,
    favorite,
    operation,
    busy,
    modified,
    description,
    rename,
    renameLayer: ctx.renameLayer,
    slots: ctx.slots,
    now: ctx.now,
    messages: ctx.messages,
    multiple: ctx.multiple,
    toggle: () => ctx.onItemToggle(id.value),
  }
}

import { computed, ref, shallowRef, type Ref } from 'vue'
import type { FileManagerMessages } from './messages'
import type { FileManagerContextMenuSlotProps, FileManagerItem, FileManagerNameValidator } from './types'
import { can, validateItemName, type FileManagerIndex } from './utils'

interface UseFileManagerActionsOptions<TData> {
  index: Readonly<Ref<FileManagerIndex<TData>>>
  rootItems: () => FileManagerItem<TData>[]
  selected: Readonly<Ref<string[]>>
  onRename: () => ((item: FileManagerItem<TData>, name: string) => unknown) | undefined
  validateName: () => FileManagerNameValidator<TData> | undefined
  onDelete: () => ((items: FileManagerItem<TData>[]) => unknown) | undefined
  confirmDelete: () => boolean
  disabled: () => boolean
  messages: () => FileManagerMessages
  /** Returns focus to an item once an action is over. */
  focus: (id: string) => void
}

/**
 * Inline rename and confirmed delete, shared by `FileTree` and `FileManager`.
 *
 * Actions picked from a menu are queued and run when the menu has finished
 * closing: the menu traps focus until then, which would otherwise steal it
 * straight back from the rename input or a dialog.
 */
export function useFileManagerActions<TData>(options: UseFileManagerActionsOptions<TData>) {
  const { index, selected } = options

  const renamingId = ref<string | null>(null)
  const pendingDelete = shallowRef<FileManagerItem<TData>[] | null>(null)
  let queued: (() => void) | null = null

  const canRename = computed(() => Boolean(options.onRename()) && !options.disabled())
  const canDelete = computed(() => Boolean(options.onDelete()) && !options.disabled())

  const itemOf = (id: string) => index.value.get(id)?.item

  function isRenamable(item: FileManagerItem<TData>) {
    return canRename.value && can(item, 'rename') && !item.trashed
  }

  function startRename(id: string | null) {
    if (id === null) return
    const item = itemOf(id)
    if (item && isRenamable(item)) renamingId.value = id
  }

  function validateRename(id: string, name: string): string | undefined {
    const item = itemOf(id)
    if (!item) return undefined
    return validateItemName(index.value, options.rootItems(), item, name, options.messages())
      ?? options.validateName()?.(name.trim(), item)
  }

  function commitRename(id: string, name: string) {
    const item = itemOf(id)
    renamingId.value = null
    if (item) options.onRename()?.(item, name)
    options.focus(id)
  }

  function cancelRename(id: string) {
    renamingId.value = null
    options.focus(id)
  }

  function requestDelete(items: FileManagerItem<TData>[]) {
    const deletable = items.filter(item => can(item, 'delete'))
    const onDelete = options.onDelete()
    if (!deletable.length || !onDelete || options.disabled()) return
    if (options.confirmDelete()) pendingDelete.value = deletable
    else onDelete(deletable)
  }

  function confirmDelete(items: FileManagerItem<TData>[]) {
    pendingDelete.value = null
    options.onDelete()?.(items)
  }

  /** Items an action on `item` applies to: the whole selection when `item` is part of it. */
  function targetsOf(item: FileManagerItem<TData>): FileManagerItem<TData>[] {
    if (!selected.value.includes(item.id)) return [item]
    return selected.value.flatMap((id) => {
      const selectedItem = itemOf(id)
      return selectedItem ? [selectedItem] : []
    })
  }

  /** Runs `action` once the open menu has closed. */
  function afterMenuCloses(action: () => void) {
    queued = action
  }

  /** Scope for the `#context-menu` slot. */
  function menuScope(item: FileManagerItem<TData> | null): FileManagerContextMenuSlotProps<TData> {
    return {
      item,
      rename: () => {
        if (item) afterMenuCloses(() => startRename(item.id))
      },
      remove: () => {
        if (item) afterMenuCloses(() => requestDelete(targetsOf(item)))
      },
      defer: afterMenuCloses,
    }
  }

  /**
   * Bind to a menu's `close-auto-focus`. Runs the queued action instead of
   * returning focus; returns whether it did.
   */
  function onMenuCloseAutoFocus(event: Event): boolean {
    if (!queued) return false
    event.preventDefault()
    const action = queued
    queued = null
    action()
    return true
  }

  return {
    renamingId,
    pendingDelete,
    canRename,
    canDelete,
    isRenamable,
    startRename,
    validateRename,
    commitRename,
    cancelRename,
    requestDelete,
    confirmDelete,
    closeDelete: () => { pendingDelete.value = null },
    targetsOf,
    afterMenuCloses,
    menuScope,
    onMenuCloseAutoFocus,
  }
}

import { computed, type Ref } from 'vue'
import type { FileManagerItem } from './types'
import { filterFileTree } from './utils'

/**
 * Client-side name filter. Derived purely from `items` and `query`, so there is
 * nothing to debounce: filtering is a single pass that only copies the folders
 * on a path to a match.
 */
export function useFileManagerSearch<TData>(
  items: Readonly<Ref<FileManagerItem<TData>[]>>,
  query: Readonly<Ref<string>>,
) {
  const normalizedQuery = computed(() => query.value.trim())
  const result = computed(() => filterFileTree(items.value, normalizedQuery.value))

  return {
    query: normalizedQuery,
    isSearching: computed(() => normalizedQuery.value.length > 0),
    items: computed(() => result.value.items),
    revealIds: computed(() => result.value.revealIds),
  }
}

import { onBeforeUnmount, ref, shallowRef, type Ref } from 'vue'
import type { FileManagerMoveEvent } from './types'
import { isDescendantOf, isFolder, type FileManagerIndex } from './utils'

const AUTO_EXPAND_DELAY = 600

interface UseFileManagerDragDropOptions<TData> {
  enabled: Readonly<Ref<boolean>>
  index: Readonly<Ref<FileManagerIndex<TData>>>
  selected: Readonly<Ref<string[]>>
  isExpanded: (id: string) => boolean
  expand: (id: string) => void
  onMove: (event: FileManagerMoveEvent<TData>) => void
  /** Whether an item may be dragged at all (permissions, trash…). Disabled items never can. */
  canDrag?: (id: string) => boolean
  /** Extra checks on a destination (e.g. write permission). `null` is the root. */
  canDropInto?: (targetId: string | null, ids: readonly string[]) => boolean
  /** Text of the drag image when several items are dragged, e.g. "3 items". */
  countLabel?: (count: number) => string
}

/**
 * Native HTML5 drag and drop. The component only reports the intent through
 * `onMove`; moving the data is up to the consumer.
 *
 * Dragging a selected item drags the whole selection, with a count as the drag
 * image. Dropping on a file drops into that file's folder. Drops into the item
 * itself, into one of its own descendants, back into the folder it already
 * lives in, or into a folder `canDropInto` refuses are rejected, and a folder
 * that refuses the drop is marked while hovered.
 */
export function useFileManagerDragDrop<TData>(options: UseFileManagerDragDropOptions<TData>) {
  const { enabled, index, selected, isExpanded, expand, onMove } = options

  const draggingIds = shallowRef<readonly string[]>([])
  const dropTargetId = ref<string | null | undefined>(undefined)
  /** A hovered folder that refuses the drop. */
  const invalidTargetId = ref<string | null | undefined>(undefined)

  let expandTimer: ReturnType<typeof setTimeout> | undefined
  let expandCandidate: string | null = null

  function clearAutoExpand() {
    clearTimeout(expandTimer)
    expandTimer = undefined
    expandCandidate = null
  }

  function scheduleAutoExpand(folderId: string | null) {
    if (folderId === expandCandidate) return
    clearAutoExpand()
    if (folderId === null || isExpanded(folderId)) return
    expandCandidate = folderId
    expandTimer = setTimeout(() => expand(folderId), AUTO_EXPAND_DELAY)
  }

  function reset() {
    clearAutoExpand()
    draggingIds.value = []
    dropTargetId.value = undefined
    invalidTargetId.value = undefined
  }

  function setCountImage(event: DragEvent, count: number) {
    if (!event.dataTransfer || typeof event.dataTransfer.setDragImage !== 'function' || !options.countLabel) return
    const badge = document.createElement('div')
    badge.textContent = options.countLabel(count)
    badge.className = 'fixed -top-96 start-0 rounded-md bg-primary px-2 py-1 text-xs font-medium text-primary-foreground shadow-md'
    document.body.append(badge)
    event.dataTransfer.setDragImage(badge, -12, -12)
    // The browser snapshots the element synchronously; it can go right away.
    setTimeout(() => badge.remove())
  }

  function onDragStart(id: string, event: DragEvent) {
    if (!enabled.value) return
    const allowed = (candidate: string) => {
      const entry = index.value.get(candidate)
      return Boolean(entry) && !entry?.item.disabled && (options.canDrag?.(candidate) ?? true)
    }
    const source = selected.value.includes(id) ? selected.value : [id]
    const ids = source.filter(candidate =>
      // Moving a folder already moves its contents.
      allowed(candidate) && !source.some(other => other !== candidate && isDescendantOf(index.value, candidate, other)))
    if (!ids.length || !ids.includes(id)) {
      event.preventDefault()
      return
    }

    draggingIds.value = ids
    if (event.dataTransfer) {
      event.dataTransfer.effectAllowed = 'move'
      // Some browsers refuse to start a drag without data.
      event.dataTransfer.setData('text/plain', ids.map(itemId => index.value.get(itemId)?.item.name ?? itemId).join('\n'))
    }
    if (ids.length > 1) setCountImage(event, ids.length)
  }

  /** A folder receives the drop itself; a file forwards it to its parent. */
  function resolveTarget(id: string | null): string | null {
    if (id === null) return null
    const entry = index.value.get(id)
    if (!entry) return null
    return isFolder(entry.item) ? id : entry.parentId
  }

  function canDropInto(targetId: string | null): boolean {
    const ids = draggingIds.value
    if (!ids.length) return false
    if (targetId !== null && index.value.get(targetId)?.item.disabled) return false

    const intoItself = ids.some(id => id === targetId || (targetId !== null && isDescendantOf(index.value, targetId, id)))
    const alreadyThere = ids.every(id => index.value.get(id)?.parentId === targetId)
    return !intoItself && !alreadyThere && (options.canDropInto?.(targetId, ids) ?? true)
  }

  function onDragOver(id: string | null, event: DragEvent) {
    if (!draggingIds.value.length) return
    const targetId = resolveTarget(id)
    if (!canDropInto(targetId)) {
      dropTargetId.value = undefined
      // Only a folder hovered directly is marked; files and empty space stay neutral.
      const alreadyThere = draggingIds.value.every(dragged => index.value.get(dragged)?.parentId === targetId)
      invalidTargetId.value = id !== null && id === targetId && !alreadyThere ? targetId : undefined
      if (event.dataTransfer) event.dataTransfer.dropEffect = 'none'
      clearAutoExpand()
      return
    }

    event.preventDefault()
    if (event.dataTransfer) event.dataTransfer.dropEffect = 'move'
    dropTargetId.value = targetId
    invalidTargetId.value = undefined
    // Only hovering the folder row itself opens it, not hovering its files.
    scheduleAutoExpand(id !== null && id === targetId ? id : null)
  }

  function onDrop(event: DragEvent) {
    const targetId = dropTargetId.value
    if (targetId !== undefined && draggingIds.value.length) {
      event.preventDefault()
      const items = draggingIds.value.flatMap((id) => {
        const item = index.value.get(id)?.item
        return item ? [item] : []
      })
      const target = targetId === null ? null : index.value.get(targetId)?.item ?? null
      onMove({ items, target })
    }
    reset()
  }

  onBeforeUnmount(clearAutoExpand)

  return {
    draggingIds,
    dropTargetId,
    invalidTargetId,
    onDragStart,
    onDragOver,
    onDrop,
    onDragEnd: reset,
    /** Clears the highlight when the pointer leaves the file manager altogether. */
    onDragLeave(event: DragEvent) {
      const next = event.relatedTarget
      const container = event.currentTarget
      if (container instanceof Node && next instanceof Node && container.contains(next)) return
      dropTargetId.value = undefined
      invalidTargetId.value = undefined
      clearAutoExpand()
    },
  }
}

import { computed, onBeforeUnmount, shallowRef } from 'vue'
import type { FileManagerMessages } from './messages'
import type {
  FileManagerConflict,
  FileManagerConflictResolution,
  FileManagerHandlerResult,
  FileManagerOperation,
  FileManagerOperationContext,
  FileManagerOperationFailure,
  FileManagerOperationResult,
  FileManagerOperationState,
} from './types'

export interface RunOptions<TData> {
  type: FileManagerOperation
  /** Number of items involved, for the default labels. */
  count: number
  itemIds?: string[]
  label?: string
  cancelable?: boolean
  /** Hide from the panel while running (inline or instant actions). Errors still show. */
  silent?: boolean
  /** Offer Retry when it fails. */
  retryable?: boolean
  /** Performs the operation. Called again on retry. */
  invoke: (context: FileManagerOperationContext<TData>) => FileManagerHandlerResult<TData> | unknown
  /** Runs once the operation succeeded, synchronously or not. */
  onSuccess?: (result: FileManagerOperationResult<TData> | undefined) => void
  /** For partial failures: the same operation with only the failed sources. */
  retryWith?: (failed: FileManagerOperationFailure<TData>[]) => RunOptions<TData> | undefined
  /** Where the result's `undo` is recorded. Undoing records into `redo`. */
  history?: 'undo' | 'redo' | 'redo-kept'
}

interface HistoryEntry<TData> {
  label: string
  count: number
  run: () => FileManagerHandlerResult<TData>
  operationId?: string
}

interface Meta<TData> {
  controller: AbortController
  options: RunOptions<TData>
  retry?: RunOptions<TData>
  timer?: ReturnType<typeof setTimeout>
}

interface UseFileManagerOperationsOptions<TData> {
  messages: () => FileManagerMessages
  external: () => FileManagerOperationState[] | undefined
  resolveConflicts: (conflicts: FileManagerConflict<TData>[]) => Promise<FileManagerConflictResolution<TData>[] | null>
  onError: (operation: FileManagerOperationState) => void
  onExternal: (event: 'cancel' | 'retry' | 'dismiss', operation: FileManagerOperationState) => void
}

const SUCCESS_DISMISS = 4000
const UNDO_DISMISS = 8000
const CANCELED_DISMISS = 2500

function isPromiseLike(value: unknown): value is PromiseLike<unknown> {
  return typeof value === 'object' && value !== null && 'then' in value && typeof value.then === 'function'
}

function isResult<TData>(value: unknown): value is FileManagerOperationResult<TData> {
  return typeof value === 'object' && value !== null
}

function errorMessage(error: unknown): string {
  if (error instanceof Error) return error.message
  return typeof error === 'string' ? error : ''
}

/**
 * Tracks what handlers do. A handler that returns a promise becomes an
 * operation with progress, cancel (through its `AbortSignal`), retry and
 * dismiss; a rejected promise is never swallowed. Results may carry `undo`,
 * which feeds Undo and Redo — the file manager never reverses anything itself.
 */
export function useFileManagerOperations<TData>(options: UseFileManagerOperationsOptions<TData>) {
  const own = shallowRef<FileManagerOperationState[]>([])
  const meta = new Map<string, Meta<TData>>()
  const undoStack = shallowRef<HistoryEntry<TData>[]>([])
  const redoStack = shallowRef<HistoryEntry<TData>[]>([])
  let counter = 0

  const isOwn = (id: string) => meta.has(id)

  function patch(id: string, update: Partial<FileManagerOperationState>) {
    own.value = own.value.map(operation => (operation.id === id ? { ...operation, ...update } : operation))
  }

  function show(state: FileManagerOperationState) {
    own.value = own.value.some(operation => operation.id === state.id)
      ? own.value.map(operation => (operation.id === state.id ? state : operation))
      : [state, ...own.value]
  }

  function remove(id: string) {
    clearTimeout(meta.get(id)?.timer)
    meta.delete(id)
    own.value = own.value.filter(operation => operation.id !== id)
  }

  function dismissLater(id: string, delay: number) {
    const entry = meta.get(id)
    if (!entry) return
    clearTimeout(entry.timer)
    entry.timer = setTimeout(() => remove(id), delay)
  }

  function run(runOptions: RunOptions<TData>): Promise<boolean> {
    const id = `operation-${++counter}`
    const controller = new AbortController()
    const messages = options.messages()
    const labelFor = (status: FileManagerOperationState['status'], count = runOptions.count) =>
      runOptions.label ?? messages.operationLabel(runOptions.type, status, count)

    const base: FileManagerOperationState = {
      id,
      type: runOptions.type,
      status: 'running',
      label: labelFor('running'),
      itemIds: runOptions.itemIds,
      cancelable: runOptions.cancelable,
      retryable: runOptions.retryable ?? true,
    }
    meta.set(id, { controller, options: runOptions })

    let visible = false
    let progress: number | undefined
    const context: FileManagerOperationContext<TData> = {
      signal: controller.signal,
      progress: (percent) => {
        progress = Math.max(0, Math.min(100, percent))
        if (visible) patch(id, { progress })
      },
      resolveConflicts: options.resolveConflicts,
    }

    const fail = (error: unknown) => {
      const state: FileManagerOperationState = { ...base, status: 'error', label: labelFor('error'), error: errorMessage(error), cancelable: false }
      show(state)
      options.onError(state)
    }

    const finish = (value: unknown) => {
      const result = isResult<TData>(value) ? value : undefined
      runOptions.onSuccess?.(result)

      const failed = result?.failed ?? []
      if (failed.length) {
        const entry = meta.get(id)
        const retry = runOptions.retryWith?.(failed)
        if (entry) entry.retry = retry
        const [first] = failed
        const detail = [messages.partialFailure(failed.length, runOptions.count), first?.error].filter(Boolean).join(': ')
        const state: FileManagerOperationState = { ...base, status: 'error', label: labelFor('error', failed.length), error: detail, retryable: Boolean(retry), cancelable: false }
        show(state)
        options.onError(state)
        return
      }

      if (result?.undo) {
        const entry: HistoryEntry<TData> = { label: result.message ?? labelFor('success'), count: runOptions.count, run: result.undo, operationId: id }
        if (runOptions.history === 'redo') {
          // An undo whose result can be redone: Redo lives in the shortcut, not the panel.
          redoStack.value = [...redoStack.value, { ...entry, operationId: undefined }]
          remove(id)
          return
        }
        else {
          undoStack.value = [...undoStack.value, entry]
          if (runOptions.history === undefined || runOptions.history === 'undo') redoStack.value = []
        }
        show({ ...base, status: 'success', label: entry.label, progress: undefined, cancelable: false, undoable: true })
        dismissLater(id, UNDO_DISMISS)
        return
      }
      if (result?.message) {
        show({ ...base, status: 'success', label: result.message, cancelable: false })
        dismissLater(id, SUCCESS_DISMISS)
        return
      }
      remove(id)
    }

    let value: unknown
    try {
      value = runOptions.invoke(context)
    }
    catch (error) {
      fail(error)
      return Promise.resolve(false)
    }

    if (!isPromiseLike(value)) {
      finish(value)
      return Promise.resolve(true)
    }

    if (!runOptions.silent) {
      visible = true
      show({ ...base, progress })
    }

    return Promise.resolve(value).then(
      (resolved) => {
        // A canceled operation stays canceled even if the handler finished anyway.
        if (controller.signal.aborted) return false
        finish(resolved)
        return true
      },
      (error: unknown) => {
        if (controller.signal.aborted) return false
        fail(error)
        return false
      },
    )
  }

  function find(id: string) {
    return [...own.value, ...(options.external() ?? [])].find(operation => operation.id === id)
  }

  function cancel(id: string) {
    const entry = meta.get(id)
    if (!entry) {
      const operation = find(id)
      if (operation) options.onExternal('cancel', operation)
      return
    }
    entry.controller.abort()
    patch(id, { status: 'canceled', label: options.messages().operationLabel(entry.options.type, 'canceled', entry.options.count), cancelable: false })
    dismissLater(id, CANCELED_DISMISS)
  }

  function retry(id: string) {
    const entry = meta.get(id)
    if (!entry) {
      const operation = find(id)
      if (operation) options.onExternal('retry', operation)
      return
    }
    const again = entry.retry ?? entry.options
    remove(id)
    void run(again)
  }

  function dismiss(id: string) {
    if (isOwn(id)) {
      remove(id)
      return
    }
    const operation = find(id)
    if (operation) options.onExternal('dismiss', operation)
  }

  function replay(entry: HistoryEntry<TData>, history: 'redo' | 'redo-kept') {
    if (entry.operationId) remove(entry.operationId)
    return run({
      type: 'other',
      count: entry.count,
      label: `${options.messages().undo}: ${entry.label}`,
      invoke: () => entry.run(),
      history,
    })
  }

  /** Undoes the latest undoable operation, or the one with `operationId`. */
  function undo(operationId?: string) {
    const stack = undoStack.value
    const index = operationId ? stack.findIndex(entry => entry.operationId === operationId) : stack.length - 1
    const entry = stack[index]
    if (!entry) return
    undoStack.value = stack.filter((_, i) => i !== index)
    void replay(entry, 'redo')
  }

  function redo() {
    const entry = redoStack.value.at(-1)
    if (!entry) return
    redoStack.value = redoStack.value.slice(0, -1)
    if (entry.operationId) remove(entry.operationId)
    void run({ type: 'other', count: entry.count, label: entry.label, invoke: () => entry.run(), history: 'redo-kept' })
  }

  const operations = computed(() => [...(options.external() ?? []), ...own.value])

  /** The operation shown on each item: running beats failed. */
  const byItem = computed(() => {
    const map = new Map<string, FileManagerOperationState>()
    for (const operation of operations.value) {
      if (operation.status !== 'running' && operation.status !== 'pending' && operation.status !== 'error') continue
      for (const itemId of operation.itemIds ?? []) {
        const current = map.get(itemId)
        if (!current || (current.status === 'error' && operation.status !== 'error')) map.set(itemId, operation)
      }
    }
    return map
  })

  onBeforeUnmount(() => {
    for (const entry of meta.values()) clearTimeout(entry.timer)
  })

  return {
    operations,
    byItem,
    run,
    cancel,
    retry,
    dismiss,
    undo,
    redo,
    canUndo: computed(() => undoStack.value.length > 0),
    canRedo: computed(() => redoStack.value.length > 0),
  }
}

export type FileManagerOperationsApi<TData> = ReturnType<typeof useFileManagerOperations<TData>>

import { computed, ref, shallowRef } from 'vue'
import type { FileManagerConflict, FileManagerConflictAction, FileManagerConflictResolution } from './types'
import { uniqueName } from './utils'

interface UseFileManagerConflictsOptions<TData> {
  /** Names already used in the folder receiving `conflict`. */
  takenNames: (conflict: FileManagerConflict<TData>) => string[]
}

/**
 * Drives the conflict dialog: one conflict at a time, with "apply to all".
 * Requests made while a dialog is open wait their turn.
 */
export function useFileManagerConflicts<TData>(options: UseFileManagerConflictsOptions<TData>) {
  const queue = shallowRef<FileManagerConflict<TData>[]>([])
  const position = ref(0)
  let resolutions: FileManagerConflictResolution<TData>[] = []
  let settle: ((value: FileManagerConflictResolution<TData>[] | null) => void) | null = null
  let chain: Promise<unknown> = Promise.resolve()
  // Names handed out for "keep both" in this batch, per destination folder.
  let assigned = new Map<string, string[]>()

  const current = computed(() => queue.value[position.value] ?? null)
  const remaining = computed(() => Math.max(0, queue.value.length - position.value - 1))

  function close(value: FileManagerConflictResolution<TData>[] | null) {
    const done = settle
    settle = null
    queue.value = []
    position.value = 0
    done?.(value)
  }

  function freeName(conflict: FileManagerConflict<TData>) {
    const key = conflict.target?.id ?? ''
    const taken = [...options.takenNames(conflict), ...(assigned.get(key) ?? [])]
    const name = uniqueName(conflict.name, taken)
    assigned.set(key, [...(assigned.get(key) ?? []), name])
    return name
  }

  function record(conflict: FileManagerConflict<TData>, action: FileManagerConflictAction) {
    // Only name clashes can be replaced or kept; anything else can only be skipped.
    const effective = conflict.reason === 'exists' ? action : 'skip'
    resolutions.push({ conflict, action: effective, name: effective === 'keep-both' ? freeName(conflict) : undefined })
  }

  /** Records a choice for the current conflict, or for it and every remaining one. */
  function choose(action: FileManagerConflictAction, applyToAll = false) {
    const pending = applyToAll ? queue.value.slice(position.value) : [current.value]
    for (const conflict of pending) if (conflict) record(conflict, action)
    position.value += pending.length
    if (position.value >= queue.value.length) close(resolutions)
  }

  function cancel() {
    close(null)
  }

  /** Asks the user about each conflict. Resolves `null` when they cancel. */
  function resolve(conflicts: FileManagerConflict<TData>[]): Promise<FileManagerConflictResolution<TData>[] | null> {
    if (!conflicts.length) return Promise.resolve([])
    const next = chain.then(() => new Promise<FileManagerConflictResolution<TData>[] | null>((done) => {
      resolutions = []
      assigned = new Map()
      settle = done
      position.value = 0
      queue.value = conflicts
    }))
    chain = next.catch(() => undefined)
    return next
  }

  return { current, remaining, choose, cancel, resolve }
}

import { shallowRef } from 'vue'
import type { FileManagerOperationContext } from './types'

export interface LoadState {
  status: 'loading' | 'error'
  error?: string
}

interface UseFileManagerLoaderOptions<TData, TTarget> {
  /** The consumer's handler; `undefined` disables loading. */
  handler: () => ((target: TTarget, context: FileManagerOperationContext<TData>) => unknown) | undefined
  context: (signal: AbortSignal) => FileManagerOperationContext<TData>
}

function errorMessage(error: unknown) {
  if (error instanceof Error) return error.message
  return typeof error === 'string' ? error : ''
}

/**
 * Keyed async loads (folder children, next pages) with loading and error
 * states. Concurrent requests for the same key share one call, so the content
 * area and the directory tree never load a folder twice.
 */
export function useFileManagerLoader<TData, TTarget>(options: UseFileManagerLoaderOptions<TData, TTarget>) {
  const states = shallowRef(new Map<string, LoadState>())
  const inflight = new Map<string, Promise<void>>()
  const done = new Set<string>()

  function setState(key: string, state: LoadState | undefined) {
    const next = new Map(states.value)
    if (state) next.set(key, state)
    else next.delete(key)
    states.value = next
  }

  /**
   * Loads `key` once. `force` loads again (retry, next page). The returned
   * promise rejects with the handler's error, after the error state is set.
   */
  function load(key: string, target: TTarget, force = false): Promise<void> {
    const handler = options.handler()
    if (!handler) return Promise.resolve()
    const running = inflight.get(key)
    if (running) return running
    if (done.has(key) && !force) return Promise.resolve()

    const controller = new AbortController()
    setState(key, { status: 'loading' })
    const promise = Promise.resolve()
      .then(() => handler(target, options.context(controller.signal)))
      .then(
        () => {
          done.add(key)
          setState(key, undefined)
        },
        (error: unknown) => {
          setState(key, { status: 'error', error: errorMessage(error) })
          throw error
        },
      )
      .finally(() => inflight.delete(key))
    inflight.set(key, promise)
    return promise
  }

  /** Forgets that `key` was loaded, e.g. after a refresh. */
  function reset(key?: string) {
    if (key === undefined) done.clear()
    else done.delete(key)
  }

  return {
    states,
    state: (key: string) => states.value.get(key),
    load,
    reset,
  }
}

import {
  ArchiveRestore,
  ClipboardPaste,
  Copy,
  CopyPlus,
  Download,
  ExternalLink,
  Eye,
  FilePlus,
  FolderPlus,
  FolderUp,
  Info,
  Link,
  PencilLine,
  RefreshCw,
  Scissors,
  Share2,
  Star,
  StarOff,
  Trash,
  Trash2,
  Upload,
} from '@lucide/vue'
import type { Component } from 'vue'
import type { FileManagerMessages } from './messages'
import type { FileManagerAction, FileManagerActionId, FileManagerItem } from './types'
import { can, isFolder, isPotentiallyUnsafe } from './utils'

/** The handler props an action depends on. */
export type FileManagerHandlerName =
  | 'onUpload' | 'onCreateFolder' | 'onCreateFile' | 'onRename' | 'onDelete' | 'onPaste' | 'onDuplicate'
  | 'onDownload' | 'onPreview' | 'onRefresh' | 'onProperties' | 'onShare' | 'onCopyLink' | 'onTrash'
  | 'onRestore' | 'onDeletePermanently' | 'onEmptyTrash' | 'onFavorite' | 'onUnfavorite'

export interface FileManagerCommandPerformers<TData> {
  open: (item: FileManagerItem<TData>) => void
  preview: (item: FileManagerItem<TData>) => void
  download: (items: FileManagerItem<TData>[]) => void
  createFolder: (parent: FileManagerItem<TData> | null) => void
  createFile: (parent: FileManagerItem<TData> | null) => void
  upload: (directory: boolean) => void
  cut: (items: FileManagerItem<TData>[]) => void
  copy: (items: FileManagerItem<TData>[]) => void
  paste: (target: FileManagerItem<TData> | null) => void
  duplicate: (items: FileManagerItem<TData>[]) => void
  rename: (item: FileManagerItem<TData>) => void
  trash: (items: FileManagerItem<TData>[]) => void
  delete: (items: FileManagerItem<TData>[]) => void
  restore: (items: FileManagerItem<TData>[]) => void
  deletePermanently: (items: FileManagerItem<TData>[]) => void
  emptyTrash: () => void
  share: (items: FileManagerItem<TData>[]) => void
  copyLink: (items: FileManagerItem<TData>[]) => void
  favorite: (items: FileManagerItem<TData>[]) => void
  unfavorite: (items: FileManagerItem<TData>[]) => void
  properties: (items: FileManagerItem<TData>[]) => void
  refresh: () => void
}

interface UseFileManagerCommandsOptions<TData> {
  messages: () => FileManagerMessages
  has: (handler: FileManagerHandlerName) => boolean
  /** Hides every action that changes data. */
  readonly: () => boolean
  isMac: () => boolean
  /** The open folder (`null` is the root), or `undefined` while a listing is shown. */
  currentFolder: () => FileManagerItem<TData> | null | undefined
  canWrite: (folder: FileManagerItem<TData> | null) => boolean
  hasClipboard: () => boolean
  isFavorite: (id: string) => boolean
  inTrash: () => boolean
  directoryUpload: () => boolean
  /** Wraps `run` so menus can defer it until they have closed. */
  schedule: (run: () => void) => () => void
  perform: FileManagerCommandPerformers<TData>
}

interface Shortcut {
  key: string
  mod?: boolean
  shift?: boolean
  alt?: boolean
}

const SHORTCUTS: Partial<Record<FileManagerActionId, Shortcut[]>> = {
  'copy': [{ key: 'c', mod: true }],
  'cut': [{ key: 'x', mod: true }],
  'paste': [{ key: 'v', mod: true }],
  'duplicate': [{ key: 'd', mod: true }],
  'rename': [{ key: 'F2' }],
  'preview': [{ key: ' ' }],
  'properties': [{ key: 'Enter', alt: true }],
  'trash': [{ key: 'Delete' }, { key: 'Backspace', mod: true }],
  'delete': [{ key: 'Delete' }, { key: 'Backspace', mod: true }, { key: 'Delete', shift: true }],
  // Plain Delete too: it is what Delete means for items already in the trash.
  'delete-permanently': [{ key: 'Delete', shift: true }, { key: 'Delete' }, { key: 'Backspace', mod: true }],
}

/** Shortcut checks, most specific first: Shift+Delete must not fall through to plain Delete. */
const SHORTCUT_ORDER: FileManagerActionId[] = ['copy', 'cut', 'paste', 'duplicate', 'rename', 'preview', 'properties', 'trash', 'delete-permanently', 'delete']

const ICONS: Record<FileManagerActionId, Component> = {
  'open': ExternalLink,
  'preview': Eye,
  'download': Download,
  'new-folder': FolderPlus,
  'new-file': FilePlus,
  'upload': Upload,
  'upload-folder': FolderUp,
  'cut': Scissors,
  'copy': Copy,
  'paste': ClipboardPaste,
  'duplicate': CopyPlus,
  'rename': PencilLine,
  'trash': Trash2,
  'delete': Trash2,
  'restore': ArchiveRestore,
  'delete-permanently': Trash,
  'empty-trash': Trash,
  'share': Share2,
  'copy-link': Link,
  'favorite': Star,
  'unfavorite': StarOff,
  'properties': Info,
  'refresh': RefreshCw,
}

function formatKey(key: string, mac: boolean) {
  if (key === ' ') return 'Space'
  if (key === 'Enter') return mac ? '↵' : 'Enter'
  if (key === 'Delete') return mac ? '⌦' : 'Del'
  if (key === 'Backspace') return mac ? '⌫' : 'Backspace'
  return key.length === 1 ? key.toUpperCase() : key
}

function formatShortcut(shortcut: Shortcut, mac: boolean) {
  const parts = [
    shortcut.mod ? (mac ? '⌘' : 'Ctrl') : '',
    shortcut.alt ? (mac ? '⌥' : 'Alt') : '',
    shortcut.shift ? (mac ? '⇧' : 'Shift') : '',
    formatKey(shortcut.key, mac),
  ].filter(Boolean)
  return parts.join(mac ? '' : '+')
}

function matches(event: KeyboardEvent, shortcut: Shortcut) {
  const mod = event.ctrlKey || event.metaKey
  const key = event.key.length === 1 ? event.key.toLowerCase() : event.key
  return key === shortcut.key
    && mod === Boolean(shortcut.mod)
    && event.shiftKey === Boolean(shortcut.shift)
    && event.altKey === Boolean(shortcut.alt)
}

/**
 * The single source of truth for what can be done: toolbar buttons, the
 * built-in context menu, keyboard shortcuts and the status bar all read it.
 * An action exists only when its handler is provided and it applies to the
 * items; it is disabled when permissions or state forbid it right now.
 */
export function useFileManagerCommands<TData>(options: UseFileManagerCommandsOptions<TData>) {
  const { has, perform } = options

  function shortcutLabel(id: FileManagerActionId): string | undefined {
    const mac = options.isMac()
    const shortcuts = SHORTCUTS[id]
    if (!shortcuts?.length) return undefined
    // On a Mac, deleting is ⌘⌫; elsewhere it is the Delete key.
    const preferred = mac ? shortcuts.find(shortcut => shortcut.key === 'Backspace') ?? shortcuts[0] : shortcuts[0]
    return preferred ? formatShortcut(preferred, mac) : undefined
  }

  /** Actions for `items` (a right-click on items, or the selection), or for the empty area when `items` is empty. */
  function resolve(items: FileManagerItem<TData>[], scope: 'items' | 'background'): FileManagerAction[] {
    const m = options.messages()
    const readonly = options.readonly()
    const actions: FileManagerAction[] = []
    const add = (id: FileManagerActionId, label: string, group: FileManagerAction['group'], enabled: boolean, run: () => void, destructive = false) => {
      actions.push({ id, label, icon: ICONS[id], shortcut: shortcutLabel(id), group, destructive, disabled: !enabled, run: options.schedule(run) })
    }

    const all = (predicate: (item: FileManagerItem<TData>) => boolean) => items.length > 0 && items.every(predicate)
    const trashed = all(item => Boolean(item.trashed))
    const anyTrashed = items.some(item => item.trashed)
    const current = options.currentFolder()

    if (scope === 'background') {
      const target = current === undefined ? undefined : current
      const writable = target !== undefined && !readonly && options.canWrite(target)
      if (!readonly && target !== undefined) {
        if (has('onCreateFolder')) add('new-folder', m.newFolder, 'new', writable, () => perform.createFolder(target))
        if (has('onCreateFile')) add('new-file', m.newFile, 'new', writable, () => perform.createFile(target))
        if (has('onUpload')) {
          add('upload', m.upload, 'new', writable, () => perform.upload(false))
          if (options.directoryUpload()) add('upload-folder', m.uploadFolder, 'new', writable, () => perform.upload(true))
        }
        if (has('onPaste')) add('paste', m.paste, 'clipboard', writable && options.hasClipboard(), () => perform.paste(target))
      }
      if (has('onEmptyTrash') && options.inTrash() && !readonly) add('empty-trash', m.emptyTrash, 'trash', true, () => perform.emptyTrash(), true)
      if (has('onRefresh')) add('refresh', m.refresh, 'info', true, () => perform.refresh())
      return actions
    }

    if (!items.length) return actions
    const [first] = items
    const single = items.length === 1 ? first : undefined

    if (single) {
      add('open', m.open, 'open', can(single, 'read') && !single.disabled, () => perform.open(single))
      if (has('onPreview') && !isFolder(single))
        add('preview', m.preview, 'open', can(single, 'read') && !isPotentiallyUnsafe(single) && !single.trashed, () => perform.preview(single))
    }

    if (!anyTrashed && !readonly) {
      if (has('onPaste')) {
        add('cut', m.cut, 'clipboard', all(item => can(item, 'move') && can(item, 'delete')), () => perform.cut(items))
        add('copy', m.copy, 'clipboard', all(item => can(item, 'copy')), () => perform.copy(items))
        // Pasting onto a folder pastes into it.
        if (single && isFolder(single))
          add('paste', m.paste, 'clipboard', options.hasClipboard() && options.canWrite(single), () => perform.paste(single))
      }
      if (has('onDuplicate')) add('duplicate', m.duplicate, 'clipboard', all(item => can(item, 'copy')), () => perform.duplicate(items))
      if (has('onRename') && single) add('rename', m.rename, 'organize', can(single, 'rename'), () => perform.rename(single))
    }

    if (!anyTrashed) {
      const starred = all(item => options.isFavorite(item.id))
      if (starred && has('onUnfavorite')) add('unfavorite', m.removeFromStarred, 'organize', true, () => perform.unfavorite(items))
      if (!starred && has('onFavorite')) add('favorite', m.addToStarred, 'organize', items.every(item => !item.disabled), () => perform.favorite(items))
      if (has('onDownload')) add('download', m.download, 'share', all(item => can(item, 'download')), () => perform.download(items))
      if (has('onShare')) add('share', m.share, 'share', all(item => can(item, 'share')), () => perform.share(items))
      if (has('onCopyLink')) add('copy-link', m.copyLink, 'share', all(item => can(item, 'share')), () => perform.copyLink(items))
    }

    if (!readonly) {
      const deletable = all(item => can(item, 'delete'))
      if (trashed) {
        if (has('onRestore')) add('restore', m.restore, 'trash', items.every(item => !item.disabled), () => perform.restore(items))
        if (has('onDeletePermanently')) add('delete-permanently', m.deletePermanently, 'trash', deletable, () => perform.deletePermanently(items), true)
      }
      else if (!anyTrashed) {
        if (has('onTrash')) add('trash', m.moveToTrash, 'trash', deletable, () => perform.trash(items), true)
        else if (has('onDelete')) add('delete', m.delete, 'trash', deletable, () => perform.delete(items), true)
        if (has('onTrash') && has('onDelete')) {
          // Offered through Shift+Delete only, like a desktop.
          actions.push({ id: 'delete', label: m.deletePermanently, icon: ICONS.delete, shortcut: shortcutLabel('delete'), group: 'trash', destructive: true, disabled: !deletable, run: options.schedule(() => perform.delete(items)) })
        }
      }
    }

    if (has('onProperties')) add('properties', m.properties, 'info', true, () => perform.properties(items))
    return actions
  }

  /** Menu entries: the resolved actions minus the ones reachable only by keyboard. */
  function menu(items: FileManagerItem<TData>[]): FileManagerAction[] {
    const actions = resolve(items, items.length ? 'items' : 'background')
    const trashAndDelete = actions.some(action => action.id === 'trash')
    return actions.filter(action => !(trashAndDelete && action.id === 'delete'))
  }

  /**
   * Runs the action bound to a key combination. Paste always targets the open
   * folder, as on a desktop. Returns whether the event was handled.
   */
  function handleKeydown(event: KeyboardEvent, selection: FileManagerItem<TData>[]): boolean {
    const candidates = [
      ...resolve(selection, 'items').filter(action => action.id !== 'paste'),
      ...resolve([], 'background').filter(action => action.id === 'paste'),
    ]
    for (const id of SHORTCUT_ORDER) {
      const shortcuts = SHORTCUTS[id] ?? []
      if (!shortcuts.some(shortcut => matches(event, shortcut))) continue
      const action = candidates.find(candidate => candidate.id === id && !candidate.disabled)
      if (!action) continue
      event.preventDefault()
      action.run()
      return true
    }
    return false
  }

  /**
   * Toolbar buttons that act on the selection stay visible but disabled when
   * nothing is selected, instead of popping in and out.
   */
  function toolbar(selection: FileManagerItem<TData>[]): FileManagerAction[] {
    const actions = resolve(selection, 'items')
    if (actions.some(action => action.id === 'download') || !has('onDownload')) return actions
    return [...actions, { id: 'download', label: options.messages().download, icon: ICONS.download, group: 'share', disabled: true, run: () => {} }]
  }

  return { resolve, menu, toolbar, handleKeydown, shortcutLabel }
}

import type { Ref } from 'vue'
import { useEventListener, useMutationObserver } from '@vueuse/core'

/**
 * Keeps keyboard focus on an element that the DOM moved. Vue reorders keyed
 * lists by moving nodes, and browsers drop focus from a node that moves: a
 * rename or a paste that re-sorts the folder would leave focus on <body>.
 *
 * After each mutation inside `root`, focus returns to the element that last
 * had it, if that element is still in the document and focus fell to <body>.
 * Focus the user moved elsewhere (Tab, a click outside) is never taken back.
 */
export function useFocusRetention(root: Readonly<Ref<HTMLElement | null>>) {
  let remembered: HTMLElement | null = null

  useEventListener(root, 'focusin', (event: FocusEvent) => {
    remembered = event.target instanceof HTMLElement ? event.target : null
  })
  useEventListener(root, 'focusout', (event: FocusEvent) => {
    const next = event.relatedTarget
    if (next instanceof Node && !root.value?.contains(next)) remembered = null
  })
  useEventListener(typeof document === 'undefined' ? null : document, 'pointerdown', (event: PointerEvent) => {
    if (!(event.target instanceof Node) || !root.value?.contains(event.target)) remembered = null
  }, { capture: true })

  useMutationObserver(root, () => {
    const element = remembered
    if (!element?.isConnected) return
    const active = document.activeElement
    if (active === element || (active && active !== document.body)) return
    element.focus({ preventScroll: true })
  }, { childList: true, subtree: true })
}

import { onBeforeUnmount, type Ref } from 'vue'
import { useEventListener } from '@vueuse/core'

/** Hold this long before an item lifts; moving earlier is a scroll. */
const LIFT_DELAY = 350
/** How far a finger may wander before the lift and still count as holding still. */
const SLOP = 10
/** Distance from a scroll container's edge that scrolls it while dragging. */
const EDGE = 40

interface UseTouchDragDropOptions {
  enabled: Readonly<Ref<boolean>>
  /** Label of the badge under the finger, e.g. "3 items". */
  countLabel: (count: number) => string
  /** How many items the drag carries once it started. */
  count: () => number
}

/**
 * Drag and drop for touch screens, where HTML5 drag and drop does not exist:
 * hold an item until it lifts, then move it. Holding still instead leaves room
 * for the long-press context menu, and moving early scrolls as usual.
 *
 * The drag is replayed as the same drag events a mouse produces (dragstart,
 * dragover, drop, dragend) at the element under the finger, so every drop
 * target (items, tree, breadcrumbs, sidebar locations, trash) and every check
 * and highlight behave exactly as they do with a mouse.
 */
export function useTouchDragDrop(root: Readonly<Ref<HTMLElement | null>>, options: UseTouchDragDropOptions) {
  let source: HTMLElement | null = null
  let start = { x: 0, y: 0 }
  let last = { x: 0, y: 0 }
  let timer: ReturnType<typeof setTimeout> | undefined
  let lifted = false
  let dragging = false
  let transfer: DataTransfer | null = null
  let ghost: HTMLElement | null = null
  let frame = 0

  function dispatch(target: Element, type: 'dragstart' | 'dragover' | 'drop' | 'dragend') {
    const event = new DragEvent(type, { bubbles: true, cancelable: true, clientX: last.x, clientY: last.y, dataTransfer: transfer })
    target.dispatchEvent(event)
    return event
  }

  function reset() {
    clearTimeout(timer)
    cancelAnimationFrame(frame)
    source?.removeAttribute('data-touch-lifted')
    ghost?.remove()
    source = null
    ghost = null
    transfer = null
    lifted = false
    dragging = false
  }

  function lift() {
    if (!source) return
    lifted = true
    source.setAttribute('data-touch-lifted', '')
    navigator.vibrate?.(10)
  }

  function begin() {
    if (!source) return false
    transfer = new DataTransfer()
    if (dispatch(source, 'dragstart').defaultPrevented) return false
    dragging = true
    ghost = document.createElement('div')
    ghost.setAttribute('aria-hidden', 'true')
    ghost.textContent = options.countLabel(options.count())
    ghost.className = 'pointer-events-none fixed left-0 top-0 z-[200] rounded-md bg-primary px-2 py-1 text-xs font-medium text-primary-foreground shadow-lg'
    document.body.append(ghost)
    return true
  }

  /** Scrolls the container under the finger when the finger nears its edge. */
  function autoScroll() {
    cancelAnimationFrame(frame)
    const under = document.elementFromPoint(last.x, last.y)
    let scroller = under instanceof HTMLElement ? under : null
    while (scroller && !(scroller.scrollHeight > scroller.clientHeight && /(auto|scroll)/.test(getComputedStyle(scroller).overflowY))) scroller = scroller.parentElement
    if (!scroller) return
    const box = scroller.getBoundingClientRect()
    const step = last.y < box.top + EDGE ? -12 : last.y > box.bottom - EDGE ? 12 : 0
    if (!step) return
    scroller.scrollTop += step
    frame = requestAnimationFrame(autoScroll)
  }

  function hover() {
    // Above the finger, so the finger does not hide it.
    if (ghost) ghost.style.transform = `translate(${last.x}px, ${last.y}px) translate(-50%, -140%)`
    const target = document.elementFromPoint(last.x, last.y)
    if (target) dispatch(target, 'dragover')
    autoScroll()
  }

  useEventListener(root, 'touchstart', (event: TouchEvent) => {
    reset()
    if (!options.enabled.value || event.touches.length !== 1) return
    const target = event.target instanceof Element ? event.target.closest<HTMLElement>('[draggable="true"]') : null
    if (!target || !root.value?.contains(target)) return
    const touch = event.touches[0]!
    source = target
    start = { x: touch.clientX, y: touch.clientY }
    last = start
    timer = setTimeout(lift, LIFT_DELAY)
  }, { passive: true })

  useEventListener(root, 'touchmove', (event: TouchEvent) => {
    if (!source) return
    const touch = event.touches[0]
    if (!touch) return
    last = { x: touch.clientX, y: touch.clientY }
    if (!lifted) {
      // Moving before the lift is a scroll: let it happen.
      if (Math.hypot(last.x - start.x, last.y - start.y) > SLOP) reset()
      return
    }
    // The browser already started scrolling: too late to take over.
    if (!event.cancelable) return reset()
    event.preventDefault()
    if (!dragging && !begin()) return reset()
    hover()
  }, { passive: false })

  function finish(drop: boolean) {
    if (dragging && source) {
      const target = drop ? document.elementFromPoint(last.x, last.y) : null
      if (target) dispatch(target, 'drop')
      dispatch(source, 'dragend')
    }
    reset()
  }

  useEventListener(root, 'touchend', (event: TouchEvent) => {
    // A drag ends without the click (or double-tap) a lifted tap would make.
    if (dragging && event.cancelable) event.preventDefault()
    finish(true)
  })
  useEventListener(root, 'touchcancel', () => finish(false))
  // Held still long enough for the context menu: that wins.
  useEventListener(root, 'contextmenu', () => {
    if (!dragging) reset()
  }, { capture: true })

  onBeforeUnmount(reset)
}
